"""Finite reproducibility checks for a three-valued MV algebra generation theorem.
Python 3, standard library only. Full infinite assertions are proved separately.
"""
from itertools import product
from math import exp, log1p


def closure(universe, gens):
    """MV subalgebra generated by tuples; truth values 0,1,2 for L3 and 0,1 for L2."""
    top = tuple(t - 1 for t in universe)
    S = {tuple(0 for _ in universe), top, *gens}
    while True:
        nxt = set(S)
        for x in S:
            nxt.add(tuple(t - 1 - a for t, a in zip(universe, x)))
            for y in S:
                nxt.add(tuple(min(t - 1, a + b) for t, a, b in zip(universe, x, y)))
        if len(nxt) == len(S):
            return S
        S = nxt


def fall(a,b):
    if b > a: return 0
    ans=1
    for j in range(b): ans*=a-j
    return ans


def is_good(profiles,k,l):
    return (all(any(x == 1 for x in profiles[j]) for j in range(k))
            and len(set(profiles[:k])) == k
            and len(set(profiles[k:])) == l)


def exact_census():
    tested=0
    for k in range(4):
        for l in range(4-k):
            if k+l == 0: continue
            universe = (3,)*k + (2,)*l
            elems = list(product(*[range(t) for t in universe]))
            for d in range(3):
                count=0
                for gens in product(elems, repeat=d):
                    profiles = tuple(tuple(g[j] for g in gens) for j in range(k+l))
                    predicted = is_good(profiles,k,l)
                    actual = len(closure(universe,gens)) == len(elems)
                    assert predicted == actual, (k,l,d,gens,profiles)
                    count += actual
                    tested += 1
                assert count == fall(3**d-2**d,k)*fall(2**d,l), (k,l,d,count)
    return tested


def log_probability(d,k,l):
    N=3**d
    B=2**d
    if k>N-B or l>B: return float('-inf')
    a = sum(log1p(-(B+j)/N) for j in range(k))
    b = sum(log1p(-j/B) for j in range(l))
    return a+b


def limiting_cases():
    d=32
    for lam,mu in [(0.7,1.3),(0.2,0.4),(1.4,0.1)]:
        k=round(lam*(1.5**d))
        l=round((2*mu*(2**d))**0.5)
        logp=log_probability(d,k,l)
        assert abs(exp(logp) - exp(-lam-mu)) < 0.003, (lam,mu,logp)

if __name__ == '__main__':
    num = exact_census()
    limiting_cases()
    print('CHECKED_GENERATOR_TUPLES',num)
    print('ALL_CHECKS_OK')
